"use strict";
GUIDE_DATA_VI.sections.push({"id":"g92","part":10,"title":"Nhịp độ dự án (Cadence)","blocks":[{"level":1,"text":"Nhịp độ dự án (Project Cadence)"},{"level":2,"text":"Quyết định tần suất và cấu trúc của các sự kiện lặp lại trong một dự án"},{"level":2,"text":"Thời lượng sprint (Sprint Duration)"},{"level":2,"text":"Họp đội định kỳ (Regular Team Meeting)"},{"level":2,"text":"Rà soát với các bên liên quan (Stakeholder Review)"},{"level":1,"text":"Thiết lập một nhịp độ (pace), hay nhịp độ (cadence), phù hợp cho một dự án"},{"level":1,"text":"Cadence đề cập đến nhịp điệu và tần suất của các sự kiện lặp lại trong một dự án, như các cuộc họp đội, các buổi rà soát với các bên liên quan và độ dài sprint"},{"level":1,"text":"Cadence cũng ảnh hưởng đến quy mô của các hạng mục công việc"},{"level":1,"text":"Việc thiết lập cadence sớm trong quá trình lập kế hoạch là rất quan trọng để đảm bảo các hạng mục công việc có quy mô phù hợp và dự án tiến triển suôn sẻ"},{"level":1,"text":"Cadence nên phản ánh tần suất kế hoạch cần thay đổi"},{"level":1,"text":"Một dự án có thể có nhiều cadence khác nhau được thể hiện trong lịch trình, các cột mốc và kế hoạch giao tiếp của nó"}]},{"id":"g93","part":10,"title":"Cấu trúc phân rã công việc (WBS)","blocks":[{"level":1,"text":"Cấu trúc phân rã công việc (Work Breakdown Structure / WBS)"},{"level":2,"text":"Một thành phần thiết yếu của quản lý dự án và là đầu vào cho các tài liệu dự án khác, bao gồm lịch trình dự án"},{"level":1,"text":"Công việc (Task)"},{"level":2,"text":"Một hành động được hoàn thành để bàn giao công việc của dự án"},{"level":1,"text":"Hoạt động (Activity)"},{"level":2,"text":"Bất kỳ công việc nào liên quan đến dự án"},{"level":1,"text":"Công việc (Work)"},{"level":2,"text":"Kết quả của việc làm một điều gì đó, chứ không phải hành động làm điều đó"},{"level":1,"text":"Lịch trình (Schedule)"},{"level":2,"text":"Chứa các sản phẩm bàn giao của WBS, thời gian và yêu cầu về nguồn lực"},{"level":1,"text":"Sản phẩm bàn giao (Deliverable)"},{"level":2,"text":"Các kết quả đầu ra của dự án"},{"level":1,"text":"Các thành phần chính của WBS"},{"level":2,"text":"Phần tử (Element)"},{"level":2,"text":"Các sản phẩm bàn giao trong một WBS"},{"level":2,"text":"Các phần tử của một WBS chỉ bao gồm danh từ"},{"level":2,"text":"Gói công việc/Phần tử đầu cuối (Work Package/Terminal Element)"},{"level":2,"text":"Phần tử thấp nhất trong mỗi cành hoặc nhánh (một phần tử không có phần tử con là một gói công việc)"},{"level":2,"text":"Các gói công việc là một phần tử công việc hướng theo kết quả, chứ không phải là một công việc (task)"},{"level":2,"text":"Cấp độ (Level)"},{"level":2,"text":"Lớp của WBS nơi một phần tử nằm"},{"level":2,"text":"Sơ đồ đánh số/Mã tài khoản (Numbering Scheme/Code of Accounts)"},{"level":2,"text":"Các phần tử được gán một con số theo vị trí của chúng trong thứ bậc"},{"level":2,"text":"Nhánh (Leg)"},{"level":2,"text":"Một nhóm các phần tử có tổ tiên chung"},{"level":2,"text":"Cành (Branch)"},{"level":2,"text":"Một hoặc nhiều phần tử không thể hiện toàn bộ phần tử cấp cao nhất trong cành"},{"level":1,"text":"Hướng dẫn thiết kế WBS"},{"level":2,"text":"Loại trừ lẫn nhau, bao quát toàn diện (Mutually Exclusive Collectively Exhaustive / MECE)"},{"level":2,"text":"Một phương pháp tổ chức và giải quyết vấn đề"},{"level":2,"text":"MECE khó thiết kế, nhưng nó giúp đảm bảo trách nhiệm giải trình cho một dự án"},{"level":2,"text":"Quy tắc 100% (The 100% Rule)"},{"level":2,"text":"Thể hiện 100% bao phủ công việc của dự án mà không bao gồm bất cứ điều gì vượt ngoài các sản phẩm bàn giao của dự án và công việc quản lý dự án"},{"level":1,"text":"Khi lập kế hoạch WBS, chỉ đưa vào các kết quả đầu ra thay vì các công việc (tasks)"},{"level":1,"text":"Trong hầu hết các dự án, khuyến nghị nên dùng bốn cấp độ hoặc ít hơn"},{"level":2,"text":"Các phần tử công việc có thể được phân rã cho đến khi đáp ứng các tiêu chí sau"},{"level":2,"text":"Đội có thể ước lượng thời gian, chi phí và nguồn lực cần thiết cho gói công việc"},{"level":2,"text":"Phần tử công việc dự kiến kéo dài theo quy tắc 8/80"},{"level":2,"text":"Phần tử tạo ra một sản phẩm bàn giao có thể đo lường được"},{"level":2,"text":"Việc phân rã phần tử thêm nữa sẽ không giúp ích cho dự án"}]},{"id":"g94","part":10,"title":"Tạo WBS","blocks":[{"level":1,"text":"Cấu trúc phân rã công việc (Work Breakdown Structure / WBS)"},{"level":2,"text":"Công cụ quản lý dự án cung cấp hình ảnh trực quan về phạm vi, các công việc và sản phẩm bàn giao của một dự án"},{"level":1,"text":"WBS cũng giúp xác định các rủi ro của dự án, ước lượng tiến độ và chi phí dự án, và phân bổ nguồn lực hiệu quả"},{"level":1,"text":"Để tạo một WBS, bạn cần tuân theo sáu bước cơ bản"},{"level":2,"text":"Xác định phạm vi"},{"level":2,"text":"Hiểu các mục tiêu, ràng buộc, yêu cầu của dự án, và xác định các bên liên quan cùng kỳ vọng của họ"},{"level":2,"text":"Để xác định phạm vi, hãy dùng các kỹ thuật sau"},{"level":2,"text":"Động não (Brainstorming)"},{"level":2,"text":"Sơ đồ tư duy (Mind Mapping)"},{"level":2,"text":"Phỏng vấn các bên liên quan (Interviewing Stakeholders)"},{"level":2,"text":"Xác định các sản phẩm bàn giao"},{"level":2,"text":"Các sản phẩm bàn giao là những sản phẩm hoặc dịch vụ hữu hình và vô hình mà dự án sẽ tạo ra, và có thể bao gồm báo cáo, phần mềm, phần cứng, tài liệu đào tạo, và nhiều thứ khác"},{"level":2,"text":"Để xác định các sản phẩm bàn giao, hãy dùng các kỹ thuật sau"},{"level":2,"text":"Phân rã (Decomposition)"},{"level":2,"text":"Sơ đồ hóa quy trình (Process Mapping)"},{"level":2,"text":"Lưu đồ (Flowcharting)"},{"level":2,"text":"Xác định các thành viên trong đội"},{"level":2,"text":"Xem xét các kỹ năng, kiến thức và kinh nghiệm cần thiết cho mỗi công việc và phân bổ các thành viên trong đội cho phù hợp"},{"level":2,"text":"Để xác định các thành viên trong đội, bạn có thể dùng Ma trận trách nhiệm (Responsibility Matrix) hoặc Biểu đồ RACI (RACI Chart)"},{"level":2,"text":"Xây dựng Cấp độ 2"},{"level":2,"text":"Cung cấp thêm chi tiết về mỗi sản phẩm bàn giao và bao gồm tất cả các công việc cần thiết để hoàn thành từng sản phẩm"},{"level":2,"text":"Để xây dựng Cấp độ 2, bạn có thể dùng các kỹ thuật như"},{"level":2,"text":"Động não (Brainstorming)"},{"level":2,"text":"Sơ đồ tư duy (Mind Mapping)"},{"level":2,"text":"Phân rã (Decomposition)"},{"level":2,"text":"Xây dựng các cấp độ còn lại"},{"level":2,"text":"Cung cấp thêm chi tiết về mỗi công việc cần thiết để hoàn thành từng sản phẩm bàn giao"},{"level":2,"text":"Để xây dựng các cấp độ còn lại, bạn có thể dùng các kỹ thuật tương tự như ở Cấp độ 2, như động não, sơ đồ tư duy hoặc phân rã"},{"level":2,"text":"Ghi lại mỗi cấp độ theo cấu trúc phân cấp, bắt đầu từ các sản phẩm bàn giao cấp cao nhất và phân rã chúng thành các thành phần nhỏ hơn"},{"level":2,"text":"Tạo Từ điển WBS (WBS Dictionary)"},{"level":2,"text":"Cung cấp thêm chi tiết mà không thể chứa hết trên sơ đồ WBS"},{"level":2,"text":"Từ điển WBS có thể tùy chỉnh, và nó nên bao gồm các phần tử sau"},{"level":2,"text":"Mã gói công việc (Work Package ID)"},{"level":2,"text":"Tên gói công việc (Work Package Name)"},{"level":2,"text":"Mô tả gói công việc (Work Package Description)"},{"level":2,"text":"Được gán cho (Assigned to)"},{"level":2,"text":"Ngày gán (Date of Assignment)"},{"level":2,"text":"Ngày đến hạn (Due Date)"},{"level":2,"text":"Chi phí ước tính (Estimated Cost)"},{"level":1,"text":"Bằng cách tạo WBS, người quản lý dự án có thể phân bổ nguồn lực và đặt tiến độ cho từng cấp độ của dự án, đảm bảo dự án tiến triển suôn sẻ và đúng lịch"}]},{"id":"g95","part":10,"title":"Backlog dự án và backlog sản phẩm","blocks":[{"level":1,"text":"Backlog dự án (project backlog) và backlog sản phẩm (product backlog) không giống nhau"},{"level":1,"text":"WBS và backlog dự án tập trung vào việc tạo ra các sản phẩm bàn giao và nhằm để lại các chi tiết thực thi cho đội"},{"level":1,"text":"WBS và backlog dự án dùng cấu trúc phân cấp để phân rã các dự án lớn thành những phần công việc nhỏ hơn"},{"level":1,"text":"Chi tiết của WBS được lưu trong từ điển WBS, trong khi chi tiết của backlog sản phẩm nằm trong các hạng mục backlog"},{"level":1,"text":"WBS có thiết kế mang tính cấu trúc hơn, trong khi backlog không có yêu cầu về thiết kế"},{"level":1,"text":"WBS vận hành với phạm vi, thời gian và chi phí cố định, trong khi backlog dự án dùng các nghi lễ Agile (agile ceremonies) để cố định thời gian và chi phí, và phạm vi công việc vẫn linh hoạt"},{"level":1,"text":"Lịch trình dự án của WBS giả định rằng mọi hạng mục phạm vi sẽ được bàn giao, trong khi lịch trình backlog giả định rằng một số hạng mục có thể không được bàn giao"},{"level":1,"text":"Giá trị không được giả định trước trong backlog dự án"},{"level":1,"text":"WBS và backlog dự án đều yêu cầu phân rã công việc thành những phần có thể quản lý được"},{"level":1,"text":"Epic"},{"level":2,"text":"Một sản phẩm bàn giao lớn được khởi phát bởi một hồ sơ kinh doanh (business case) và tương đương với cấp độ 1 của một WBS"},{"level":1,"text":"Tính năng (Feature)"},{"level":2,"text":"Nhỏ hơn một epic và kéo dài 1-3 vòng lặp (iterations)"},{"level":1,"text":"Câu chuyện người dùng (User Story)"},{"level":2,"text":"Sản phẩm bàn giao Agile nhỏ nhất, tương đương với một gói công việc về quy mô và bản chất"},{"level":1,"text":"Epic, tính năng (features) và câu chuyện người dùng (user stories) là các sản phẩm hướng theo sản phẩm bàn giao, dùng danh từ"},{"level":1,"text":"WBS và backlog sản phẩm xác định những gì đội cần bàn giao"}]},{"id":"g96","part":10,"title":"Các công việc của dự án (Tasks)","blocks":[{"level":1,"text":"Các gói công việc được tạo ra bởi một WBS, và các câu chuyện người dùng được tạo ra bởi một backlog"},{"level":1,"text":"Trong quản lý dự án, một công việc (task) là một hành động cụ thể được thực hiện để hoàn thành một sản phẩm bàn giao"},{"level":1,"text":"Các công việc không được thể hiện trực quan ở cấp độ WBS hoặc câu chuyện người dùng"},{"level":1,"text":"Các công việc không phải lúc nào cũng cần thiết cho mọi gói công việc hoặc câu chuyện người dùng"},{"level":1,"text":"Một số hướng dẫn giúp xác định khi nào nên tạo các công việc"},{"level":2,"text":"Nếu đội muốn một danh sách việc cần làm (to-do list) để quản lý công việc hiện có"},{"level":2,"text":"Nếu một gói công việc có nhiều hành động với các chủ sở hữu khác nhau"},{"level":2,"text":"Nếu có nhiều mối phụ thuộc trong một câu chuyện người dùng hoặc gói công việc"},{"level":2,"text":"Nếu nó cải thiện cách đội làm việc hoặc cách quản lý dự án"}]},{"id":"g97","part":10,"title":"Các mối phụ thuộc (Dependencies)","blocks":[{"level":1,"text":"Xác định các hoạt động của dự án là một bước quan trọng khi lập lịch trình dự án"},{"level":1,"text":"Các mối phụ thuộc (Dependencies)"},{"level":2,"text":"Đề cập đến các mối quan hệ giữa các hoạt động"},{"level":2,"text":"Các mối phụ thuộc kiểm soát thứ tự các sự kiện trong một dự án"},{"level":1,"text":"Khi hai hoạt động phụ thuộc vào nhau, chúng có mối quan hệ tiền nhiệm - kế tiếp (predecessor-successor)"},{"level":1,"text":"Các mối phụ thuộc có thể được thể hiện trực quan theo nhiều cách, bao gồm liệt kê các hoạt động tiền nhiệm cho mỗi mối phụ thuộc trong lịch trình dự án, hoặc thông qua biểu đồ Gantt (Gantt charts) và sơ đồ mạng dự án"},{"level":1,"text":"4 loại mối phụ thuộc"},{"level":2,"text":"Kết thúc để bắt đầu (Finish-to-Start / FS)"},{"level":2,"text":"Hoạt động 2 bắt đầu sau khi Hoạt động 1 kết thúc"},{"level":2,"text":"Bắt đầu để bắt đầu (Start-to-Start / SS)"},{"level":2,"text":"Hoạt động 2 bắt đầu sau khi Hoạt động 1 bắt đầu"},{"level":2,"text":"Kết thúc để kết thúc (Finish-to-Finish / FF)"},{"level":2,"text":"Hoạt động 2 kết thúc sau khi Hoạt động 1 kết thúc"},{"level":2,"text":"Bắt đầu để kết thúc (Start-to-Finish / SF)"},{"level":2,"text":"Hoạt động 2 chỉ kết thúc sau khi Hoạt động 1 đã bắt đầu"},{"level":1,"text":"Trên một sơ đồ hoặc biểu đồ Gantt, loại mối quan hệ quyết định cách liên kết hai hoạt động về mặt trực quan"},{"level":1,"text":"4 loại mối phụ thuộc logic"},{"level":2,"text":"Bắt buộc (Mandatory)"},{"level":2,"text":"Không thể tránh khỏi và thường phát sinh do lý do pháp lý hoặc hợp đồng"},{"level":2,"text":"Tùy ý (Discretionary)"},{"level":2,"text":"Thường thể hiện một chiến lược nhằm tối ưu hóa hiệu quả, giảm chi phí hoặc cải thiện chất lượng"},{"level":2,"text":"Bên ngoài (External)"},{"level":2,"text":"Nằm ngoài tầm kiểm soát của tổ chức"},{"level":2,"text":"Nội bộ (Internal)"},{"level":2,"text":"Loại mà tổ chức có thể kiểm soát"},{"level":1,"text":"Không có loại mối phụ thuộc nào vốn dĩ tốt hơn các loại khác"},{"level":1,"text":"Các mối phụ thuộc bắt buộc thường không linh hoạt và dễ quản lý hơn, nhưng chúng cũng có rủi ro cao hơn"},{"level":1,"text":"Việc hiểu chi tiết từng mối phụ thuộc giúp đảm bảo dự án tuân thủ trong khi vẫn quản lý các đánh đổi"}]},{"id":"g98","part":10,"title":"Các kỹ thuật ước lượng","blocks":[{"level":1,"text":"Các ước lượng cực kỳ giá trị vì chúng cho bạn một điểm khởi đầu cho dự án của mình"},{"level":1,"text":"Có nhiều kỹ thuật khác nhau để ước lượng chi phí và thời lượng dự án, mỗi kỹ thuật đều có ưu điểm và hạn chế riêng"},{"level":1,"text":"Một số kỹ thuật phổ biến nhất để ước lượng chi phí và thời lượng dự án"},{"level":2,"text":"Ước lượng từ trên xuống (Top-Down Estimating)"},{"level":2,"text":"Bắt đầu bằng việc ước lượng tổng chi phí hoặc thời lượng của dự án hoặc các sản phẩm bàn giao chính, sau đó phân rã ước lượng thành các thành phần nhỏ hơn"},{"level":2,"text":"Ước lượng từ dưới lên (Bottom-Up Estimating)"},{"level":2,"text":"Ước lượng chi phí hoặc thời lượng của từng hoạt động, công việc hoặc câu chuyện người dùng riêng lẻ, sau đó tổng hợp chúng lại để tạo ra ước lượng cho dự án"},{"level":2,"text":"Ước lượng tương tự (Analogous Estimating)"},{"level":2,"text":"Sử dụng dữ liệu lịch sử từ các dự án tương tự để ước lượng chi phí hoặc thời lượng của dự án hiện tại"},{"level":2,"text":"Ước lượng mô hình tham số (Parametric Model Estimating)"},{"level":2,"text":"Kết hợp dữ liệu lịch sử với các mô hình toán học để ước lượng chi phí hoặc thời lượng của một dự án"},{"level":2,"text":"Việc kết hợp ước lượng ba điểm với bất kỳ kỹ thuật ước lượng nào khác có thể đưa ra một ước lượng tinh tế và chính xác hơn"},{"level":2,"text":"Cách tiếp cận này xem xét nhiều kịch bản có thể xảy ra và tính ước lượng trung bình dựa trên ba giá trị: lạc quan, bi quan và khả dĩ nhất"},{"level":2,"text":"Dưới đây là một ví dụ về việc dùng ước lượng ba điểm"},{"level":2,"text":"Giả sử một đội đang ước lượng thời gian cần thiết để hoàn thành một dự án phát triển phần mềm. Dùng kỹ thuật ước lượng ba điểm, họ xác định các ước lượng sau"},{"level":2,"text":"Ước lượng lạc quan (O): 4 tháng"},{"level":2,"text":"Ước lượng khả dĩ nhất (M): 6 tháng"},{"level":2,"text":"Ước lượng bi quan (P): 8 tháng"},{"level":2,"text":"Để tính ước lượng trung bình, họ có thể dùng công thức"},{"level":2,"text":"( O + 4M + P ) / 6"},{"level":2,"text":"Trong trường hợp này, ước lượng trung bình sẽ là"},{"level":2,"text":"(4 + 4(6) + 8) / 6 = 5.33 tháng"},{"level":2,"text":"Ước lượng này xem xét các kịch bản tốt nhất, tệ nhất và khả dĩ nhất, mang lại một ước lượng toàn diện và chính xác hơn"},{"level":2,"text":"Còn ước lượng thời gian và nỗ lực thì sao?"},{"level":2,"text":"Một cách tiếp cận phổ biến là ước lượng thời gian và nỗ lực cho các hoạt động của dự án, chẳng hạn như dùng thời lượng và số giờ công việc hoặc điểm câu chuyện (story points)"}]},{"id":"g99","part":10,"title":"Phân bổ nguồn lực","blocks":[{"level":1,"text":"Phân bổ nguồn lực (Resource Allocation)"},{"level":2,"text":"Nó bao gồm việc phân bổ cả nguồn lực con người và vật chất, vì nguồn lực vốn (capital resources) thường được dùng để chi trả cho chúng"},{"level":2,"text":"Nó mang lại nhiều lợi ích cho một dự án"},{"level":2,"text":"Rõ ràng (Clarity)"},{"level":2,"text":"Công bằng (Parity)"},{"level":2,"text":"Khám phá (Discovery)"},{"level":2,"text":"Tính hợp lệ (Validity)"},{"level":1,"text":"Quy trình gán nguồn lực bao gồm hai hoạt động"},{"level":2,"text":"Gán các vai trò thông qua Ma trận phân công trách nhiệm (Responsibilities Assignment Matrix / RAM)"},{"level":2,"text":"Gán nguồn lực con người và vật chất bằng một công cụ lập lịch dự án"},{"level":1,"text":"Trong giai đoạn khởi tạo (initiation phase) của dự án, Ma trận (RAM) được khởi tạo và các thành viên trong đội cùng với vai trò tương ứng của họ được thêm vào"},{"level":1,"text":"Ma trận RACI bao gồm bốn vai trò như sau"},{"level":2,"text":"Thực hiện (Responsible / R)"},{"level":2,"text":"Người sẽ thực hiện công việc được gán"},{"level":2,"text":"Chịu trách nhiệm (Accountable / A)"},{"level":2,"text":"Người sẽ chịu trách nhiệm về công việc cuối cùng"},{"level":2,"text":"Được tham vấn (Consulted / C)"},{"level":2,"text":"Người có thể cung cấp chuyên môn về công việc nhưng không trực tiếp tham gia"},{"level":2,"text":"Được thông báo (Informed / I)"},{"level":2,"text":"Người cần nắm được việc hoàn thành công việc"},{"level":1,"text":"Ma trận phân công trách nhiệm (Responsibility Assignment Matrix / RAM) là một công cụ quan trọng để xác định vai trò và trách nhiệm của dự án"},{"level":1,"text":"Để quản lý nguồn lực dự án hiệu quả, cũng nên sử dụng một công cụ lập lịch quản lý dự án"},{"level":2,"text":"Hầu hết các dự án dùng phần mềm dự án để tạo lịch trình, xác định đường cơ sở (baselines) và báo cáo về kết quả dự án"},{"level":2,"text":"Phần mềm lập lịch này thường bao gồm một danh sách toàn diện"},{"level":2,"text":"Các hoạt động của dự án (Project Activities)"},{"level":2,"text":"Các cột mốc (Milestones)"},{"level":2,"text":"Các mối phụ thuộc (Dependencies)"},{"level":2,"text":"Các ngày tương ứng (Corresponding Dates)"},{"level":2,"text":"Thông tin này có thể được thể hiện trực quan bằng các bảng, bảng Kanban (Kanban boards) và biểu đồ Gantt (Gantt charts)"},{"level":2,"text":"Phần mềm cũng duy trì một danh sách nguồn lực bao gồm mọi nguồn lực của dự án, năng lực của chúng và các chi phí liên quan"},{"level":1,"text":"Việc theo dõi các gán nguồn lực có thể giúp xác định các vấn đề tiềm ẩn"},{"level":1,"text":"Lịch trình dự án (Project Schedule)"},{"level":2,"text":"Chứa các hoạt động cần thiết để hoàn thành công việc của dự án"},{"level":2,"text":"Tiến độ dự án (Project Timeline)"},{"level":2,"text":"Nguồn lực (Resources)"},{"level":2,"text":"Ngày đến hạn (Due Dates)"},{"level":2,"text":"Các mối phụ thuộc. Lập kế hoạch dự án (Creating a Project Plan)"}]},{"id":"g100","part":10,"title":"Tạo Kế hoạch Dự án","blocks":[{"level":1,"text":"Mục tiêu của việc thu thập các chỉ số (metrics) là cải thiện kết quả"},{"level":1,"text":"Sơ đồ Mạng lưới Dự án (Project Network Diagrams)"},{"level":2,"text":"Trình bày trực quan các mối quan hệ logic và sự phụ thuộc giữa các hoạt động của dự án"},{"level":1,"text":"Phương pháp Đường găng (Critical Path Method)"},{"level":2,"text":"Kỹ thuật xác định chuỗi hoạt động phụ thuộc dài nhất, để xác định thời lượng tối thiểu của dự án và làm nổi bật các hoạt động cần được giám sát chặt chẽ"},{"level":1,"text":"Sản phẩm Khả thi Tối thiểu (Minimum Viable Product)"},{"level":2,"text":"Đề cập đến việc phát triển một phiên bản cơ bản của sản phẩm hoặc giải pháp chỉ bao gồm các tính năng cốt lõi cần thiết để mang lại giá trị cho người dùng hoặc khách hàng ban đầu"},{"level":1,"text":"Dự trữ Dự án (Project Reserves)"},{"level":2,"text":"Các nguồn lực được phân bổ, như thời gian, ngân sách hoặc kế hoạch dự phòng, dành riêng để xử lý các rủi ro không lường trước, sự bất định hoặc thay đổi trong quá trình thực hiện dự án"},{"level":1,"text":"Đường cơ sở Dự án (Project Baselines)"},{"level":2,"text":"Các điểm tham chiếu đã được phê duyệt và thống nhất, xác định phạm vi, tiến độ và chi phí ban đầu của dự án"},{"level":1,"text":"Ngân sách Dự án (Project Budget)"},{"level":2,"text":"Thể hiện các nguồn lực tài chính đã được lập kế hoạch dành cho việc thực hiện dự án, bao gồm chi phí ước tính cho nhân công, vật liệu, thiết bị và các chi phí khác"}]},{"id":"g101","part":10,"title":"Sơ đồ Mạng lưới Dự án","blocks":[{"level":1,"text":"Trong quản lý dự án, cần phải lập một lịch trình bao gồm mọi hoạt động của dự án, các mối phụ thuộc và ước tính thời gian"},{"level":1,"text":"Lịch trình dự án thường được trình bày dưới dạng bảng tính hoặc biểu đồ Gantt (Gantt chart)"},{"level":2,"text":"Biểu đồ Gantt dùng các thanh ngang để thể hiện thời lượng hoạt động, khiến biểu đồ tạo ra có thể cồng kềnh và khó xem"},{"level":2,"text":"Sơ đồ Mạng lưới Dự án (Project Network Diagram)"},{"level":2,"text":"Còn gọi là sơ đồ mạng lưới lịch trình dự án, cung cấp hình ảnh trực quan rõ ràng và súc tích về lịch trình dự án bằng các mũi tên và các hình chữ nhật cùng kích thước"},{"level":1,"text":"Các Phương pháp Sơ đồ Khác nhau (Different Diagram Methods)"},{"level":2,"text":"Phương pháp Sơ đồ Quan hệ Trước sau (Precedence Diagram Method - PDM)"},{"level":2,"text":"Một kiểu sơ đồ dự án phổ biến sử dụng hình chữ nhật và mũi tên để chỉ ra các mối phụ thuộc giữa các hoạt động"},{"level":2,"text":"Một biểu đồ PDM có thể được phác thảo và chồng thêm thời lượng cùng các phép tính bằng một kỹ thuật sơ đồ khác"},{"level":2,"text":"Kỹ thuật Đánh giá và Rà soát Chương trình (Program Evaluation and Review Technique - PERT)"},{"level":2,"text":"Được thiết kế để minh họa thời lượng, các hoạt động và các mối phụ thuộc của dự án"},{"level":2,"text":"Kỹ thuật này sử dụng ba ước tính thời lượng cho mỗi hoạt động"},{"level":2,"text":"Lạc quan (Optimistic)"},{"level":2,"text":"Bi quan (Pessimistic)"},{"level":2,"text":"Khả năng cao nhất (Most Likely)"},{"level":2,"text":"Ước tính PERT giúp tính toán các ước tính thời gian thực tế"},{"level":2,"text":"Phương pháp Đường găng (Critical Path Method - CPM)"}]},{"id":"g102","part":10,"title":"Phương pháp Đường găng","blocks":[{"level":1,"text":"Phương pháp Đường găng (Critical Path Method - CPM)"},{"level":2,"text":"Được dùng trong sơ đồ mạng lưới dự án để kết hợp thời lượng, các hoạt động, các mối phụ thuộc, ước tính PERT và các phép tính bổ sung"},{"level":1,"text":"Để tính đường găng, cần xác định chuỗi hoạt động phụ thuộc dài nhất, mà chuỗi này chưa chắc đã là các hoạt động quan trọng nhất về mặt mang lại giá trị"},{"level":1,"text":"7 Bước Phân tích Đường găng (7 Steps of Critical Path Analysis)"},{"level":2,"text":"Vẽ các hoạt động và mối phụ thuộc của dự án"},{"level":2,"text":"Tính thời lượng ước tính PERT cho mỗi hoạt động"},{"level":2,"text":"Thực hiện lần duyệt xuôi (forward pass) để tính ngày bắt đầu sớm (early start) và ngày kết thúc sớm (early finish)"},{"level":2,"text":"Thực hiện lần duyệt ngược (backward pass) để tính ngày bắt đầu muộn (late start) và ngày kết thúc muộn (late finish)"},{"level":2,"text":"Tính tổng dự trữ thời gian (total float - TF)"},{"level":2,"text":"Tổng Dự trữ Thời gian (Total Float - TF)"},{"level":2,"text":"Được tính bằng cách lấy ngày kết thúc muộn nhất trừ đi ngày kết thúc sớm nhất của hoạt động"},{"level":2,"text":"Tính dự trữ thời gian tự do (free float - FF)"},{"level":2,"text":"Dự trữ Thời gian Tự do (Free Float - FF)"},{"level":2,"text":"Được tính bằng cách lấy ngày bắt đầu sớm nhất trừ đi ngày kết thúc sớm nhất của hoạt động"},{"level":2,"text":"Xác định đường găng"},{"level":2,"text":"Đường Găng (Critical Path)"},{"level":2,"text":"Chuỗi các hoạt động phải được hoàn thành đúng hạn để đáp ứng thời hạn của dự án"},{"level":1,"text":"Bằng cách sử dụng phân tích đường găng, bạn có thể đảm bảo dự án đi đúng tiến độ và đội dự án tập trung vào các hoạt động quan trọng nhất"},{"level":1,"text":"Đường găng là đường dài nhất xuyên qua sơ đồ mạng lưới xét về thời lượng"},{"level":1,"text":"CPM là một kỹ thuật quản lý dự án dùng để xác định chuỗi các hoạt động phụ thuộc có thời lượng dài nhất trong dự án"}]},{"id":"g103","part":10,"title":"Tính Hữu ích của các Kết quả đầu ra từ CPM","blocks":[{"level":1,"text":"Phân tích Đường găng (Critical Path Analysis - CPA)"},{"level":2,"text":"Kỹ thuật quản lý dự án giúp lập kế hoạch, lập lịch trình và quản lý các dự án phức tạp một cách hiệu quả"},{"level":1,"text":"Đường găng thể hiện thời lượng dài nhất của dự án và giúp xác định các hoạt động then chốt đối với thành công của dự án"},{"level":1,"text":"5 Lợi ích Chính của việc thực hiện CPA"},{"level":2,"text":"Phân bổ nguồn lực hiệu quả"},{"level":2,"text":"Giúp người quản lý dự án xác định các hoạt động then chốt cần nhiều sự chú ý và nguồn lực nhất, từ đó phân bổ nguồn lực hiệu quả"},{"level":2,"text":"Ước tính thời gian hoàn thành dự án chính xác"},{"level":2,"text":"Việc thực hiện phân tích đường găng giúp người quản lý dự án ước tính chính xác thời gian cần thiết để hoàn thành dự án"},{"level":2,"text":"Cải thiện khả năng nhìn thấy toàn cảnh dự án (project visibility)"},{"level":2,"text":"Cung cấp hình ảnh trực quan về đường găng của dự án, giúp người quản lý dự án nhận diện các điểm nghẽn và trì hoãn tiềm ẩn"},{"level":2,"text":"Quản lý rủi ro tốt hơn"},{"level":2,"text":"Phân tích đường găng giúp người quản lý dự án xác định các hoạt động then chốt dễ bị rủi ro và trì hoãn nhất"},{"level":2,"text":"Cải thiện giao tiếp"},{"level":2,"text":"Cung cấp hình ảnh rõ ràng, súc tích về đường găng của dự án, giúp truyền đạt trạng thái và tiến độ dự án tới các bên liên quan"},{"level":1,"text":"7 Bước Phân tích Đường găng (7 Steps of Critical Path Analysis)"},{"level":2,"text":"Vẽ các hoạt động và mối phụ thuộc của dự án"},{"level":2,"text":"Tính thời lượng ước tính PERT cho mỗi hoạt động"},{"level":2,"text":"Thực hiện lần duyệt xuôi để tính ngày bắt đầu sớm và ngày kết thúc sớm"},{"level":2,"text":"Trong lần duyệt xuôi, bạn sẽ xác định hai giá trị cho mỗi hoạt động: ngày bắt đầu sớm và ngày kết thúc sớm"},{"level":2,"text":"Bắt đầu Sớm (Early Start - ES)"},{"level":2,"text":"Thời điểm bắt đầu sớm nhất có thể của một hoạt động, dựa trên thời gian cần thiết để hoàn thành mọi hoạt động tiền nhiệm"},{"level":2,"text":"Kết thúc Sớm (Early Finish - EF)"},{"level":2,"text":"Thời điểm kết thúc sớm nhất có thể của một hoạt động dựa trên thời lượng của nó"},{"level":2,"text":"Các công thức sau có thể dùng để tính ES và EF"},{"level":2,"text":"ES = EF lớn nhất trong số mọi hoạt động tiền nhiệm trực tiếp"},{"level":2,"text":"EF = ES + t, trong đó t là thời lượng của hoạt động"},{"level":2,"text":"Thực hiện lần duyệt ngược để tính ngày bắt đầu muộn và ngày kết thúc muộn"},{"level":2,"text":"Trong lần duyệt ngược, bạn bắt đầu từ cuối dự án và đi ngược lại qua các mối phụ thuộc cho đến khi tới điểm bắt đầu của dự án"},{"level":2,"text":"Đối với mỗi hoạt động, bạn sẽ tính hai giá trị mới trong lần duyệt ngược: ngày bắt đầu muộn và ngày kết thúc muộn"},{"level":2,"text":"Bắt đầu Muộn (Late Start - LS)"},{"level":2,"text":"Thời điểm bắt đầu muộn nhất có thể của một hoạt động mà vẫn đảm bảo dự án hoàn thành đúng hạn"},{"level":2,"text":"Kết thúc Muộn (Late Finish - LF)"},{"level":2,"text":"Thời điểm kết thúc muộn nhất có thể của một hoạt động mà vẫn đảm bảo dự án hoàn thành đúng hạn"},{"level":2,"text":"Để tính LS và LF, dùng các công thức sau"},{"level":2,"text":"LF = LS nhỏ nhất trong số mọi hoạt động kế tiếp"},{"level":2,"text":"LS = LF – t, trong đó t là thời lượng của hoạt động"},{"level":2,"text":"Lần duyệt ngược dùng LF nhỏ nhất vì nó thể hiện khoảng thời gian dài nhất còn lại phía trước trong dự án"},{"level":2,"text":"Tính tổng dự trữ thời gian (TF)"},{"level":2,"text":"Tổng Dự trữ Thời gian (TF)"},{"level":2,"text":"Đo lường khoảng thời gian một hoạt động có thể bị trì hoãn mà không ảnh hưởng đến tổng tiến độ của dự án"},{"level":2,"text":"TF được tính cho mỗi hoạt động bằng một trong hai công thức sau"},{"level":2,"text":"TF = LS – ES"},{"level":2,"text":"TF = LF – EF"},{"level":2,"text":"Tính dự trữ thời gian tự do (FF)"},{"level":2,"text":"Dự trữ Thời gian Tự do (FF)"},{"level":2,"text":"Khoảng thời gian một hoạt động có thể chờ trước khi bắt đầu mà không ảnh hưởng đến bất kỳ hoạt động nào khác"},{"level":2,"text":"Lấy ngày bắt đầu sớm nhỏ nhất trong số mọi hoạt động kế tiếp trực tiếp trừ đi ngày kết thúc sớm của công việc đang được tính"},{"level":2,"text":"Xác định đường găng"},{"level":2,"text":"Đường găng được định nghĩa là danh sách mọi hoạt động có tổng dự trữ thời gian bằng không"},{"level":1,"text":"Nhìn ở cấp độ cao, mọi thứ dường như đều là mục trên đường găng, nhưng thực tế chỉ có một số phần nhất định của công việc trở thành mục trên đường găng"},{"level":1,"text":"CPM là một kỹ thuật giúp lập kế hoạch, lập lịch trình và quản lý các dự án phức tạp một cách hiệu quả bằng cách xác định đường găng"}]},{"id":"g104","part":11,"title":"Sản phẩm Khả thi Tối thiểu","blocks":[{"level":1,"text":"Sản phẩm Khả thi Tối thiểu (Minimum Viable Product - MVP)"},{"level":2,"text":"Phiên bản ban đầu của một sản phẩm thể hiện đủ chức năng để người dùng đầu tiên (early adopters) sử dụng và đưa ra phản hồi"},{"level":1,"text":"Khi các bên liên quan thấy một sản phẩm thật, hoạt động được từ sớm trong dự án, điều đó cũng giúp xây dựng niềm tin vào thành công của dự án"},{"level":1,"text":"Các Tính năng khác nhau của MVP (Different Features of MVP)"},{"level":2,"text":"Tạo Dự án (Project Creation)"},{"level":2,"text":"Cho phép người dùng tạo dự án mới, đặt mục tiêu và thời hạn của dự án, và phân công thành viên đội nhóm làm việc trong dự án"},{"level":2,"text":"Quản lý Công việc (Task Management)"},{"level":2,"text":"Cho phép người dùng tạo công việc trong dự án, phân công cho thành viên đội nhóm, đặt thời hạn và theo dõi tiến độ"},{"level":2,"text":"Chế độ xem Lịch (Calendar View)"},{"level":2,"text":"Cho phép người dùng xem mốc thời gian, thời hạn của dự án và lịch làm việc của đội nhóm ở chế độ xem lịch để giúp quản lý lịch trình dự án"},{"level":2,"text":"Giao tiếp (Communication)"},{"level":2,"text":"Bao gồm tính năng nhắn tin trong ứng dụng cho phép các thành viên đội nhóm giao tiếp với nhau"},{"level":2,"text":"Báo cáo (Reporting)"},{"level":2,"text":"Cho phép người dùng xem tiến độ và tỷ lệ hoàn thành của dự án, theo dõi thời gian dành cho các công việc và tạo báo cáo về trạng thái dự án"},{"level":1,"text":"MVP sẽ cung cấp một bộ công cụ cơ bản để người quản lý dự án CNTT quản lý dự án, giao tiếp với thành viên đội nhóm và theo dõi tiến độ"},{"level":1,"text":"Trong phase khởi tạo dự án (Initiation), một bản tuyên bố phạm vi sơ bộ được soạn thảo"},{"level":1,"text":"Khi dự án tiến triển, đội nhóm hiểu biết thêm về phạm vi và yêu cầu của dự án, cho phép họ tạo ra bản tuyên bố phạm vi chi tiết hơn"},{"level":2,"text":"Cùng một mẫu có thể dùng cho cả bản tuyên bố phạm vi sơ bộ và chi tiết, nhưng bản chi tiết có thể bao gồm thêm các trường như rủi ro dự án đáng kể, các cột mốc (milestones) và yêu cầu của nhà cung cấp"},{"level":2,"text":"Việc tạo bản tuyên bố phạm vi chi tiết tạo cơ hội xác nhận kế hoạch dự án so với bản tuyên bố phạm vi sơ bộ"},{"level":2,"text":"Các trường sau thường được đưa vào bản tuyên bố phạm vi"},{"level":2,"text":"Mô tả Phạm vi Dự án (Project Scope Description)"},{"level":2,"text":"Tiêu chí Nghiệm thu Dự án (Project Acceptance Criteria)"},{"level":2,"text":"Các Sản phẩm Bàn giao của Dự án (Project Deliverables)"},{"level":2,"text":"Các Loại trừ của Dự án (Project Exclusions)"},{"level":2,"text":"Các Giả định (Assumptions)"},{"level":2,"text":"Các Ràng buộc (Constraints)"},{"level":2,"text":"Nó có thể bao gồm thêm các trường như"},{"level":2,"text":"Các Cột mốc (Milestones)"},{"level":2,"text":"Các Yêu cầu (Requirements)"},{"level":2,"text":"Các Công việc (Tasks)"},{"level":2,"text":"Các Rủi ro (Risks)"},{"level":2,"text":"Ngân sách (Budget)"},{"level":2,"text":"Các Ước tính (Estimates)"},{"level":2,"text":"Các Phương pháp Ước tính (Estimation Methods)"},{"level":1,"text":"Ước tính Chi phí (Cost Estimates)"},{"level":2,"text":"Chi phí dự án bao gồm cả chi phí trực tiếp và chi phí gián tiếp"},{"level":2,"text":"Chi phí Trực tiếp (Direct Costs)"},{"level":2,"text":"Phát sinh như một kết quả trực tiếp của dự án và có thể gắn với một nguồn lực hoặc hoạt động cụ thể"},{"level":2,"text":"Chi phí Gián tiếp (Indirect Costs)"},{"level":2,"text":"Chi phí chung (overhead) hỗ trợ nhiều hoạt động mà không thể quy trực tiếp cho một nguồn lực hay hoạt động cụ thể"},{"level":2,"text":"Khi ước tính chi phí dự án, chi phí trực tiếp luôn được đưa vào, và cần đơn giá chi phí nguồn lực để tổng hợp chi phí"},{"level":1,"text":"Bản tuyên bố phạm vi phát triển từ phiên bản sơ bộ thành phiên bản chi tiết trong suốt dự án"},{"level":1,"text":"Ước tính chi phí bao gồm việc xem xét chi phí trực tiếp và gián tiếp, dùng đơn giá chi phí nguồn lực để ước tính chi phí ở các cấp độ khác nhau của dự án"}]},{"id":"g105","part":11,"title":"Dự trữ Dự án","blocks":[{"level":1,"text":"Trong quá trình thực hiện dự án, các tình huống không lường trước có thể phát sinh, và ngân sách dự án cần bao gồm các khoản dự trữ tài chính để bảo vệ trước các trở ngại"},{"level":1,"text":"2 Loại Dự trữ (2 Types of Reserves)"},{"level":2,"text":"Dự trữ Dự phòng (Contingency Reserve)"},{"level":2,"text":"Một vùng đệm thời gian và chi phí đã được tính toán để bao phủ các rủi ro đã được ghi nhận (\"known unknowns\" - những điều chưa biết đã biết)"},{"level":2,"text":"Dự trữ dự phòng còn được gọi là \"vùng đệm dự phòng\" (contingency buffer)"},{"level":2,"text":"Dự trữ Quản lý (Management Reserve)"},{"level":2,"text":"Một khoản thời gian hoặc tiền bạc bổ sung dùng làm dự phòng cho \"unknown unknowns\" (những điều chưa biết chưa biết)"},{"level":2,"text":"Khi yêu cầu dự trữ quản lý, hãy đưa ra lý do chính đáng thấu đáo và kế hoạch phục hồi"},{"level":2,"text":"Dự trữ quản lý dùng để bao phủ các thay đổi lớn của dự án"},{"level":2,"text":"Thay đổi nhà cung cấp"},{"level":2,"text":"Thời gian tiếp nhận nhân sự (onboarding time)"},{"level":2,"text":"Thay đổi hợp đồng"},{"level":2,"text":"Thay đổi chi phí nguồn lực"},{"level":2,"text":"Các vấn đề chuỗi cung ứng toàn cầu"},{"level":1,"text":"Khoản dự trữ cung cấp nguồn kinh phí dự phòng cho dự án trong trường hợp bất kỳ rủi ro nào đã xác định xảy ra"}]},{"id":"g106","part":11,"title":"Tính toán Dự trữ Dự án","blocks":[{"level":1,"text":"Nhiều phương pháp khác nhau để tính dự trữ dự án"},{"level":2,"text":"Phần trăm Chi phí Dự án (Percentage of a Project's Cost)"},{"level":2,"text":"Một phần trăm của chi phí ước tính của dự án được đưa vào xem xét"},{"level":2,"text":"Phân tích Monte Carlo (Monte Carlo Analysis)"},{"level":2,"text":"Một kỹ thuật mô phỏng nổi tiếng sử dụng ước tính ba điểm để xây dựng phân phối xác suất"},{"level":2,"text":"Nó kiểm đếm tần suất của các kết quả tổng thể của dự án"},{"level":2,"text":"Nó chồng một đường xác suất tích lũy lên biểu đồ histogram để chỉ ra xác suất dự án nằm trong ngân sách"},{"level":2,"text":"Giá trị Tiền tệ Kỳ vọng (Expected Monetary Value - EMV)"},{"level":2,"text":"Yêu cầu đánh giá xác suất và tác động của từng rủi ro"},{"level":2,"text":"Xác suất và tác động tài chính khi xảy ra của mỗi rủi ro được nhân với nhau"},{"level":2,"text":"EMV = Xác suất x Tác động"},{"level":2,"text":"Phép tính EMV giúp các công ty ra quyết định"},{"level":2,"text":"Phân tích Cây quyết định (Decision Tree Analysis)"},{"level":2,"text":"Một công cụ ra quyết định cho việc lập kế hoạch dự phòng (ra quyết định định lượng)"},{"level":2,"text":"Một cây quyết định có ba thành phần: quyết định, các lựa chọn và các kết quả"},{"level":2,"text":"Để tính EMV cho mỗi kết quả, cộng dồn EMV của kết quả của từng lựa chọn để xác định chi phí EMV"},{"level":2,"text":"Phân tích cây quyết định phù hợp nhất với các dự án lớn có rủi ro tác động cao và xác suất cao"}]},{"id":"g107","part":11,"title":"Đường cơ sở Dự án","blocks":[{"level":1,"text":"Đường cơ sở Dự án (Project Baseline)"},{"level":2,"text":"Đóng vai trò là điểm tham chiếu ban đầu cho dự án"},{"level":1,"text":"Đường cơ sở dự án gồm ba phần"},{"level":2,"text":"Đường cơ sở Phạm vi (Scope Baseline)"},{"level":2,"text":"Phạm vi gốc từ bản tuyên bố phạm vi chi tiết"},{"level":2,"text":"Đường cơ sở Tiến độ (Schedule Baseline)"},{"level":2,"text":"Tổng thời lượng dự án được ghi lại từ lịch trình dự án"},{"level":2,"text":"Đường cơ sở Chi phí (Cost Baseline)"},{"level":2,"text":"Chi phí kỳ vọng cộng với dự trữ dự phòng"},{"level":1,"text":"Việc thiết lập đường cơ sở giúp ngăn ngừa phát sinh phạm vi (scope creep), vượt chi phí và trì hoãn trong dự án"},{"level":1,"text":"Việc tạo đường cơ sở dự án giúp ước tính và theo dõi tiến độ dự án tốt hơn"},{"level":1,"text":"Một đường cơ sở tốt hỗ trợ quy trình kiểm soát thay đổi bằng cách làm nguồn sự thật (source of truth) cho phạm vi gốc"},{"level":1,"text":"4 Bước Chính để Tạo Đường cơ sở Dự án (4 Main Steps in Creating a Project Baseline)"},{"level":2,"text":"Xác định phạm vi và nhận diện các sản phẩm bàn giao chính"},{"level":2,"text":"Rà soát bản tuyên bố phạm vi chi tiết và xác định chính xác các sản phẩm bàn giao thiết yếu quyết định phạm vi của dự án"},{"level":2,"text":"Thiết lập lịch trình với thời lượng và thời hạn của dự án"},{"level":2,"text":"Tạo đường cơ sở tiến độ và xác định tổng thời lượng của dự án"},{"level":2,"text":"Tạo đường cơ sở chi phí"},{"level":2,"text":"Tổng hợp ước tính chi phí dự án cộng với dự trữ dự phòng"},{"level":2,"text":"Xin phê duyệt của các bên liên quan (stakeholder approval)"},{"level":2,"text":"Chia sẻ với các bên liên quan để có được sự đồng thuận của họ"}]},{"id":"g108","part":11,"title":"Ngân sách Dự án","blocks":[{"level":1,"text":"Ngân sách dự án bao gồm mọi chi phí nguồn lực và thể hiện tổng chi phí của dự án, trong đó có ước tính chi phí, dự trữ dự phòng và dự trữ quản lý"},{"level":1,"text":"Một ngân sách được xác định rõ ràng tạo thêm tính khách quan cho việc ra quyết định tài chính, giúp vượt qua sự chống đối"},{"level":1,"text":"Ràng buộc Ngân sách (Budget Constraint)"},{"level":2,"text":"Đề cập đến giới hạn hoặc sự hạn chế đặt ra đối với số tiền có sẵn cho dự án"},{"level":1,"text":"Các khoản Dự trữ (Reserves)"},{"level":2,"text":"Đề cập đến các khoản tiền dành riêng để bao phủ các chi phí bất ngờ hoặc rủi ro có thể phát sinh trong vòng đời dự án"},{"level":1,"text":"Cập nhật ngân sách khi có thay đổi là điều thiết yếu"},{"level":1,"text":"Tài liệu (documentation) là một thành phần thiết yếu khác trong việc quản lý ngân sách dự án"},{"level":1,"text":"Việc ghi lại các cập nhật cho các ước tính và việc sử dụng các khoản dự trữ cũng rất quan trọng"},{"level":1,"text":"Việc giữ ngân sách luôn được cập nhật là rất quan trọng"},{"level":2,"text":"Thay đổi có thể xảy ra bất kỳ lúc nào trong dự án, và rất dễ quên mất các chi tiết"},{"level":1,"text":"Các ràng buộc ngân sách rất quan trọng đối với thành công của dự án"},{"level":2,"text":"Quản lý các khoản dự trữ, duy trì tài liệu và giữ ngân sách luôn được cập nhật đều là những thành phần then chốt để đảm bảo dự án đi đúng tiến độ và nằm trong nguồn lực sẵn có. Tìm mua Giải pháp (Procuring Solutions)"}]},{"id":"g109","part":11,"title":"Tổng quan Kế hoạch Đảm bảo Chất lượng","blocks":[{"level":1,"text":"Đảm bảo Chất lượng (Quality Assurance - QA)"},{"level":2,"text":"Bao gồm một loạt các thủ tục có thể ảnh hưởng đến mọi khía cạnh của dự án"},{"level":2,"text":"Sự phân biệt giữa QA và QC (kiểm soát chất lượng - Quality Control) có thể không rõ ràng"},{"level":2,"text":"QA"},{"level":2,"text":"Quy trình và giao thức (processes and protocols)"},{"level":2,"text":"QC"},{"level":2,"text":"Kiểm tra công việc đã hoàn thành"},{"level":1,"text":"Kế hoạch QA (QA Plan)"},{"level":2,"text":"Được xây dựng trong phase lập kế hoạch (Planning) và duy trì tính liên quan trong suốt thời gian của dự án"},{"level":2,"text":"Kế hoạch QA giải đáp một số câu hỏi then chốt"},{"level":2,"text":"Làm thế nào để xác minh công việc dự án đáp ứng kỳ vọng?"},{"level":2,"text":"Làm thế nào để ngăn ngừa khuyết tật chất lượng?"},{"level":2,"text":"Làm thế nào để nhận diện và cải thiện các quy trình kém hiệu quả?"},{"level":1,"text":"Kiểm chứng (Verification)"},{"level":2,"text":"Quy trình nội bộ xác nhận một cách khách quan rằng sản phẩm bàn giao đáp ứng các tiêu chuẩn chất lượng"},{"level":1,"text":"Xác nhận (Validation)"},{"level":2,"text":"Quy trình mang tính chủ quan diễn ra bên ngoài đội nhóm và tập trung vào các sản phẩm bàn giao đã hoàn thành"},{"level":1,"text":"Kiểm chứng (verification) đo lường chất lượng nội bộ, trong khi xác nhận (validation) đo lường mức độ mong muốn"},{"level":1,"text":"Kế hoạch QA bao gồm các thành phần sau"},{"level":2,"text":"Tiêu chuẩn Chất lượng (Quality Standards)"},{"level":2,"text":"Ghi lại mọi tiêu chuẩn ngành hoặc tiêu chuẩn pháp lý liên quan, như quy định về sức khỏe, áp dụng cho dự án"},{"level":2,"text":"Mục tiêu Chất lượng (Quality Objectives)"},{"level":2,"text":"Tạo danh sách các mục tiêu chất lượng có thể đo lường được, bao gồm giao hàng đúng hạn và số lượng khuyết tật"},{"level":2,"text":"Vai trò và Trách nhiệm (Roles and Responsibilities)"},{"level":2,"text":"Xác định các cá nhân chịu trách nhiệm quản lý chương trình, tuân thủ các tiêu chuẩn và đánh giá sản phẩm theo các tiêu chuẩn"},{"level":2,"text":"Sản phẩm Bàn giao và Cách tiếp cận (Deliverables and Approach)"},{"level":2,"text":"Xác định mọi sản phẩm bàn giao và quy trình thuộc phạm vi các hoạt động QA"},{"level":1,"text":"Đội dự án nên tổ chức các cuộc họp định kỳ để đánh giá hiệu suất và cải thiện"},{"level":2,"text":"Các phương pháp Agile gọi thực hành này là \"retrospectives\" (hồi cố), trong khi thuật ngữ chung hơn là \"lessons learned\" (bài học kinh nghiệm)"},{"level":2,"text":"Bài học kinh nghiệm có thể đề cập đến những suy ngẫm cuối dự án"},{"level":2,"text":"Vào cuối dự án, mục tiêu là cải thiện các dự án trong tương lai"},{"level":2,"text":"Các buổi hồi cố và sự kiện bài học kinh nghiệm được ghi lại trong tài liệu bài học kinh nghiệm (lessons learned document)"},{"level":1,"text":"Kiểm tra (Inspection)"},{"level":2,"text":"Một loại công cụ QC bao gồm việc xem xét một sản phẩm đã hoàn thành và so sánh với kết quả mong đợi"},{"level":2,"text":"Đánh giá sprint (sprint reviews), hồi cố và kiểm thử phần mềm đều là ví dụ về kiểm tra trong kế hoạch chất lượng của dự án"},{"level":1,"text":"Kiểm toán (Audit)"},{"level":2,"text":"Rà soát các quy trình để xác định các nguồn gây ra vấn đề chất lượng tiềm ẩn"},{"level":2,"text":"Các phát hiện kiểm toán xảy ra trước khi công việc được tạo ra"},{"level":1,"text":"Quy trình Mua sắm (Procurement Process)"},{"level":2,"text":"Bao gồm việc thu mua hàng hóa và dịch vụ từ các nguồn bên ngoài thông qua nhiều phương thức"},{"level":2,"text":"Quy trình mua sắm bao gồm nhiều bước"},{"level":2,"text":"Xác định các yêu cầu"},{"level":2,"text":"Gửi yêu cầu mua hàng"},{"level":2,"text":"Thu hút báo giá hoặc đề xuất từ các nhà cung cấp"},{"level":2,"text":"Đánh giá và lựa chọn nhà cung cấp"},{"level":2,"text":"Quản lý đơn hàng"},{"level":2,"text":"Duy trì hồ sơ và thanh toán"},{"level":2,"text":"Đơn đặt hàng (purchase orders), thỏa thuận dịch vụ tổng thể (master service agreements) và hợp đồng mua sắm (procurement contracts) là các tạo tác (artifacts) phổ biến trong quy trình mua sắm"},{"level":1,"text":"Trong quá trình đánh giá giải pháp, Bản mô tả công việc (Statement of Work - SOW), Điều khoản tham chiếu (Terms of Reference - TOR) và Nghiên cứu thị trường (Market Research) là những yếu tố then chốt để tối ưu việc lựa chọn nhà cung cấp và sản phẩm"},{"level":2,"text":"Bản mô tả công việc (Statement of Work - SOW)"},{"level":2,"text":"Tài liệu chính thức quy định công việc mà nhà cung cấp phải hoàn thành, xác định phạm vi dự án và các yêu cầu kỹ thuật"},{"level":2,"text":"Điều khoản tham chiếu (Terms of Reference - TOR)"},{"level":2,"text":"Tập trung vào mối quan hệ giữa các bên liên quan và nhấn mạnh việc bàn giao công việc"},{"level":2,"text":"Nghiên cứu thị trường (Market Research)"},{"level":2,"text":"Được thực hiện bởi các chuyên gia mua sắm về sản phẩm, dịch vụ, nhà cung cấp và xu hướng ngành"},{"level":1,"text":"Việc đánh giá các giải pháp thay thế và xem xét chi phí đầu tư (capital expenses - CapEx) và chi phí vận hành (operational expenses - OpEx) mang lại sự linh hoạt trong việc tìm ra các lựa chọn phù hợp nhất"},{"level":1,"text":"Có ba loại hợp đồng chính mà người quản lý dự án gặp phải"},{"level":2,"text":"Trọn gói (Fixed-price)"},{"level":2,"text":"Thiết lập một mức giá cố định cho một phạm vi công việc cố định và đặt phần lớn rủi ro hợp đồng lên nhà cung cấp"},{"level":2,"text":"Có ba loại"},{"level":2,"text":"Trọn gói cứng (Firm fixed-price)"},{"level":2,"text":"Trọn gói cộng phí khuyến khích (Fixed-price plus incentive fee)"},{"level":2,"text":"Trọn gói có điều chỉnh giá theo kinh tế (Fixed-price with economic price adjustment)"},{"level":2,"text":"Chi phí cộng thêm (Cost-plus)"},{"level":2,"text":"Hoàn trả cho nhà cung cấp mọi chi phí nguồn lực và cộng thêm một khoản phí lợi nhuận"},{"level":2,"text":"Chi phí cộng phí cố định (Cost-plus fixed fee)"},{"level":2,"text":"Chi phí cộng phí khuyến khích (Cost-plus incentive fee)"},{"level":2,"text":"Chi phí cộng phí thưởng (Cost-plus award fee)"},{"level":2,"text":"Chi phí cộng phần trăm chi phí (Cost-plus percentage of cost)"},{"level":2,"text":"Lai (Hybrid)"},{"level":2,"text":"Kết hợp các đặc điểm của trọn gói và chi phí cộng thêm"},{"level":1,"text":"Các điều khoản hợp đồng như bảo hành (warranties) và thỏa thuận không tiết lộ (non-disclosure agreements) rất quan trọng trong mua sắm"},{"level":2,"text":"Bảo hành đảm bảo rằng nhà cung cấp sẽ xử lý các khuyết tật"},{"level":2,"text":"Thỏa thuận không tiết lộ bảo vệ thông tin bảo mật"},{"level":1,"text":"Người quản lý dự án đóng vai trò trong việc quản lý mối quan hệ với nhà cung cấp"}]},{"id":"g110","part":11,"title":"Các Loại Kiểm thử Phần mềm","blocks":[{"level":1,"text":"Kiểm thử phần mềm rất quan trọng đối với các tổ chức CNTT vì nó giúp đảm bảo phần mềm đang được phát triển đáp ứng các yêu cầu và hoạt động như dự định"},{"level":1,"text":"Một số lý do tại sao kiểm thử phần mềm quan trọng đối với các tổ chức CNTT"},{"level":2,"text":"Đảm bảo Chất lượng (Quality Assurance)"},{"level":2,"text":"Kiểm chứng và xác nhận phần mềm, đảm bảo nó đáp ứng các tiêu chuẩn chất lượng mong muốn"},{"level":2,"text":"Tiết kiệm chi phí (Cost-effective)"},{"level":2,"text":"Phát hiện và sửa lỗi trong phase phát triển"},{"level":2,"text":"Sự hài lòng của Người dùng (User Satisfaction)"},{"level":2,"text":"Đảm bảo phần mềm đáp ứng các yêu cầu và kỳ vọng của người dùng"},{"level":2,"text":"Tuân thủ (Compliance)"},{"level":2,"text":"Đảm bảo phần mềm đáp ứng các yêu cầu, giảm nguy cơ bị phạt pháp lý và tài chính"},{"level":2,"text":"Uy tín (Reputation)"},{"level":2,"text":"Giúp ngăn ngừa sự cố bằng cách duy trì uy tín và độ tin cậy của tổ chức"},{"level":1,"text":"Các bài kiểm thử có thể được phân thành hai loại"},{"level":2,"text":"Thủ công (Manual)"},{"level":2,"text":"Bao gồm việc một người thực hiện thủ công từng bước của bài kiểm thử, mỗi lần một cú nhấp chuột"},{"level":2,"text":"Kiểm thử thủ công có tính thích ứng cao, vì con người có thể phát hiện những thay đổi nhỏ trong giao diện phần mềm"},{"level":2,"text":"Tự động (Automated)"},{"level":2,"text":"Bao gồm việc máy móc thực hiện các bài kiểm thử thông qua các kịch bản phần mềm (scripts) đánh dấu lỗi để nhà phát triển xử lý"},{"level":2,"text":"Các bài kiểm thử tự động cần sự can thiệp của con người để xây dựng và duy trì"},{"level":1,"text":"Kiểm thử Đơn vị (Unit Testing)"},{"level":2,"text":"Bao gồm việc kiểm thử đơn vị chức năng nhỏ nhất để đảm bảo tính năng của nó"},{"level":1,"text":"Kiểm thử Hồi quy (Regression Testing)"},{"level":2,"text":"Bao gồm việc chạy lại các bài kiểm thử hiện có sau một thay đổi mã nguồn để đảm bảo thay đổi đó không ảnh hưởng đến bất kỳ chức năng hiện có nào"},{"level":1,"text":"Kiểm thử Khói (Smoke Testing)"},{"level":2,"text":"Một bài kiểm thử hệ thống ở cấp độ cao xác nhận rằng các tính năng chính của phần mềm đang hoạt động trước khi tiến hành kiểm thử chi tiết"},{"level":1,"text":"Kiểm thử Nghiệm thu Người dùng (User Acceptance Testing)"},{"level":2,"text":"Đánh giá các đầu ra cuối cùng so với đặc tả để xác định xem người dùng có chấp nhận sản phẩm hay không"},{"level":1,"text":"Kiểm thử Hiệu năng (Performance Testing)"},{"level":2,"text":"Đánh giá sự ổn định và tốc độ của hệ thống dưới nhiều tải công việc khác nhau"},{"level":1,"text":"Kiểm thử Chịu tải (Stress Testing)"},{"level":2,"text":"Một cách tiếp cận kiểm thử đánh giá sự ổn định và tốc độ của hệ thống dưới nhiều tải công việc khác nhau"}]},{"id":"g111","part":11,"title":"Tạo Kế hoạch Kiểm thử","blocks":[{"level":1,"text":"Kế hoạch kiểm thử bao gồm chiến lược kiểm thử (test strategy), một lịch trình cụ thể các sự kiện, các bài kiểm thử cần chạy và các bài kiểm thử thủ công và tự động"},{"level":1,"text":"Tính minh bạch đảm bảo sự hiểu biết chung về các kỳ vọng chất lượng của sản phẩm"},{"level":1,"text":"Các kế hoạch kiểm thử có thể tái sử dụng, vì mọi dự án phát triển đều bao gồm Kiểm thử Nghiệm thu Người dùng (User Acceptance Testing - UAT)"},{"level":1,"text":"Có một số yếu tố trong một kế hoạch kiểm thử"},{"level":2,"text":"Phạm vi (Scope)"},{"level":2,"text":"Cung cấp cái nhìn tổng quan về phạm vi dự án, bao gồm mục tiêu, các loại trừ và các kịch bản khác"},{"level":2,"text":"Loại Kiểm thử (Test Type)"},{"level":2,"text":"Xác định các loại kiểm thử được dùng trong dự án, các bài kiểm thử dùng để làm gì và khi nào được dùng"},{"level":2,"text":"Lịch trình (Schedule)"},{"level":2,"text":"Phác thảo ngày bắt đầu và ngày kết thúc cho việc kiểm thử và các ngày cho từng loại kiểm thử"},{"level":2,"text":"Nguồn lực (Resources)"},{"level":2,"text":"Liệt kê các hệ thống và nhân sự cần thiết để hoàn thành quy trình kiểm thử cùng vai trò và trách nhiệm của các thành viên đội nhóm"},{"level":2,"text":"Môi trường (Environment)"},{"level":2,"text":"Phác thảo các cấu hình, phần cứng và phần mềm cần thiết để tạo môi trường kiểm thử"},{"level":2,"text":"Công cụ (Tools)"},{"level":2,"text":"Liệt kê mọi yêu cầu phần mềm cần thiết để xây dựng và chạy các bài kiểm thử, đồng thời báo cáo kết quả kiểm thử, ghi nhận khuyết tật và chia sẻ tiến độ"},{"level":2,"text":"Quản lý Khuyết tật (Defect Management)"},{"level":2,"text":"Phác thảo các kỳ vọng rõ ràng cho việc xử lý khuyết tật, bao gồm hệ thống dùng để ghi nhận, khi nào ghi nhận khuyết tật và cần ghi lại thông tin gì"},{"level":2,"text":"Quản lý Rủi ro (Risk Management)"},{"level":2,"text":"Tóm tắt các rủi ro liên quan đến quy trình kiểm thử, bao gồm các rủi ro mới được phát hiện trong quá trình thực hiện kế hoạch kiểm thử"},{"level":2,"text":"Tiêu chí Kết thúc (Exit Parameter)"},{"level":2,"text":"Đặt ra tiêu chuẩn mà đội QA dùng để đo lường và đội phát triển dùng để viết mã"},{"level":1,"text":"Các hoạt động xác nhận khác nhau"},{"level":2,"text":"Thỏa thuận Mức Dịch vụ (Service Level Agreements - SLA)"},{"level":2,"text":"Hợp đồng dịch vụ phác thảo các kỳ vọng về hiệu suất và hậu quả khi không đáp ứng kỳ vọng"},{"level":2,"text":"SLA không thể đảm bảo một mức hiệu suất cụ thể"},{"level":2,"text":"Nhiều SLA gắn với dịch vụ đúng hạn hoặc hiệu suất hệ thống, giúp cải thiện lịch trình"},{"level":2,"text":"Hỗ trợ Sau Triển khai (Post-implementation Support)"},{"level":2,"text":"Cung cấp hỗ trợ tiếp nhận sau ngày go-live (ngày vận hành chính thức)"},{"level":2,"text":"Hỗ trợ sau triển khai trong kế hoạch dự án rất quan trọng vì nó thường bị bỏ qua sau khi triển khai"},{"level":2,"text":"Hỗ trợ sau triển khai khác với hỗ trợ kỹ thuật"},{"level":2,"text":"Bảo hành (Warranty)"},{"level":2,"text":"Một nghĩa vụ theo hợp đồng đảm bảo sản phẩm đáp ứng các yêu cầu cụ thể"},{"level":2,"text":"Bảo hành yêu cầu nguồn lực để hỗ trợ trong suốt thời gian bảo hành"}]},{"id":"g112","part":12,"title":"Kế hoạch Quản lý Dự án","blocks":[{"level":1,"text":"Kế hoạch quản lý dự án bao gồm một loạt tài liệu chi tiết về các sản phẩm bàn giao, cách tiếp cận và các chỉ số hiệu suất của đội dự án"},{"level":1,"text":"Kế hoạch Dự án (Project Plan)"},{"level":2,"text":"Một nguồn lực năng động phát triển trong suốt vòng đời dự án"},{"level":1,"text":"Nhà tài trợ dự án (project sponsor), người quản lý dự án và các nhà quản lý chức năng (functional managers) phải phê duyệt kế hoạch dự án"},{"level":1,"text":"Kế hoạch Quản lý Dự án gồm các nội dung sau, điểm qua ngắn gọn từng nội dung và các thành phần phụ thuộc của chúng"},{"level":2,"text":"Giới thiệu (Introduction)"},{"level":2,"text":"Bối cảnh (Background)"},{"level":2,"text":"Mục đích của Kế hoạch (Purpose of the Plan)"},{"level":2,"text":"Phạm vi của Kế hoạch (Scope of the Plan)"},{"level":2,"text":"Bản Tuyên bố Phạm vi Dự án (Project Scope Statement)"},{"level":2,"text":"Mục tiêu Dự án (Project Objectives)"},{"level":2,"text":"Các Sản phẩm Bàn giao (Deliverables)"},{"level":2,"text":"Các Loại trừ khỏi Phạm vi (Scope Exclusions)"},{"level":2,"text":"Các Giả định và Ràng buộc (Assumptions and Constraints)"},{"level":2,"text":"Tiêu chí Nghiệm thu (Acceptance Criteria)"},{"level":2,"text":"Cấu trúc Phân rã Công việc (Work Breakdown Structure - WBS) hoặc Backlog"},{"level":2,"text":"Mô tả WBS hoặc Backlog (WBS or Backlog Description)"},{"level":2,"text":"Thứ bậc WBS hoặc Backlog (WBS or Backlog Hierarchy)"},{"level":2,"text":"Từ điển WBS hoặc Backlog (WBS or Backlog Dictionary)"},{"level":2,"text":"Kế hoạch Nguồn lực (Resource Plan)"},{"level":2,"text":"Yêu cầu Nguồn lực (Resource Requirements)"},{"level":2,"text":"Phân bổ Nguồn lực (Resource Allocation)"},{"level":2,"text":"Lịch trình Nguồn lực (Resource Schedule)"},{"level":2,"text":"Quản lý Nguồn lực (Resource Management)"},{"level":2,"text":"Lịch trình Dự án (Project Schedule)"},{"level":2,"text":"Mốc thời gian Dự án (Project Timeline)"},{"level":2,"text":"Lịch trình Cột mốc (Milestone Schedule)"},{"level":2,"text":"Phân tích Đường Găng (Critical Path Analysis)"},{"level":2,"text":"Đường cơ sở Tiến độ (Schedule Baseline)"},{"level":2,"text":"Kế hoạch Quản lý Chất lượng (Quality Management Plan)"},{"level":2,"text":"Mục tiêu Chất lượng (Quality Objectives)"},{"level":2,"text":"Chỉ số Chất lượng (Quality Metrics)"},{"level":2,"text":"Các hoạt động Kiểm soát Chất lượng (Quality Control Activities)"},{"level":2,"text":"Các hoạt động Đảm bảo Chất lượng (Quality Assurance Activities)"},{"level":2,"text":"Kế hoạch Quản lý Rủi ro (Risk Management Plan)"},{"level":2,"text":"Nhận diện Rủi ro (Risk Identification)"},{"level":2,"text":"Đánh giá Rủi ro (Risk Assessment)"},{"level":2,"text":"Lập kế hoạch Ứng phó Rủi ro (Risk Response Planning)"},{"level":2,"text":"Giám sát và Kiểm soát Rủi ro (Risk Monitoring and Control)"},{"level":2,"text":"Kế hoạch Giao tiếp (Communication Plan)"},{"level":2,"text":"Nhận diện Các bên liên quan (Stakeholder Identification)"},{"level":2,"text":"Các Kênh Giao tiếp (Communication Channels)"},{"level":2,"text":"Mục tiêu Giao tiếp (Communication Objectives)"},{"level":2,"text":"Tần suất Giao tiếp (Communication Frequency)"},{"level":2,"text":"Kế hoạch Quản lý Các bên liên quan (Stakeholder Management Plan)"},{"level":2,"text":"Phân tích Các bên liên quan (Stakeholder Analysis)"},{"level":2,"text":"Kế hoạch Gắn kết Các bên liên quan (Stakeholder Engagement Plan)"},{"level":2,"text":"Kế hoạch Giao tiếp với Các bên liên quan (Stakeholder Communication Plan)"},{"level":2,"text":"Các Đường cơ sở Dự án (Project Baselines)"},{"level":2,"text":"Đường cơ sở Phạm vi (Scope Baseline)"},{"level":2,"text":"Đường cơ sở Tiến độ (Schedule Baseline)"},{"level":2,"text":"Đường cơ sở Chi phí (Cost Baseline)"},{"level":2,"text":"Ngân sách Dự án (Project Budget)"},{"level":2,"text":"Phân rã Ngân sách (Budget Breakdown)"},{"level":2,"text":"Ước tính Chi phí (Cost Estimation)"},{"level":2,"text":"Theo dõi Ngân sách (Budget Tracking)"},{"level":2,"text":"Phê duyệt Kế hoạch Dự án (Project Plan Approval)"},{"level":2,"text":"Quy trình Phê duyệt (Approval Process)"},{"level":2,"text":"Các Phê duyệt Cần thiết (Approvals Required)"},{"level":2,"text":"Người ký (Signatories)"},{"level":2,"text":"Phụ lục (Appendices)"},{"level":2,"text":"Bảng Thuật ngữ (Glossary of Terms)"},{"level":2,"text":"Danh sách Từ viết tắt (List of Acronyms)"},{"level":2,"text":"Kế hoạch Quản lý Thay đổi (Change Management Plan)"},{"level":2,"text":"Kế hoạch Quản lý Vấn đề (Issue Management Plan)"},{"level":2,"text":"Kế hoạch Mua sắm (Procurement Plan)"},{"level":2,"text":"Kế hoạch Đào tạo (Training Plan)"},{"level":2,"text":"Các Kế hoạch và Tài liệu Liên quan khác (Other Relevant Plans and Documents)"}]},{"id":"g113","part":12,"title":"Tổng quan Quy trình Mua sắm","blocks":[{"level":1,"text":"Quy trình Mua sắm (Procurement Process)"},{"level":2,"text":"Thu mua hàng hóa và dịch vụ từ các công ty khác"},{"level":1,"text":"Quy trình mua sắm có các chuyên gia chuyên trách chuyên sâu về nó"},{"level":1,"text":"Các Bước của Quy trình Mua sắm (Steps of the Procurement Process)"},{"level":2,"text":"Xác định các yêu cầu"},{"level":2,"text":"PM (người quản lý dự án) xác định các yêu cầu mua sắm để đáp ứng mục tiêu của dự án"},{"level":2,"text":"Gửi yêu cầu mua hàng (purchase requisition)"},{"level":2,"text":"PM yêu cầu sự hỗ trợ từ đội mua sắm để thu mua nguồn lực"},{"level":2,"text":"Hoàn thành quy trình chào thầu (solicitation)"},{"level":2,"text":"Chuyên gia mua sắm chuẩn bị yêu cầu để thu hút báo giá, đấu thầu hoặc đề xuất từ các nhà cung cấp"},{"level":2,"text":"Đánh giá và lựa chọn nhà cung cấp"},{"level":2,"text":"Hội đồng đánh giá đánh giá và chấm điểm các đề xuất của nhà cung cấp dựa trên các tiêu chí khách quan đã được xác định trước"},{"level":2,"text":"Quản lý đơn hàng"},{"level":2,"text":"Chuyên gia mua sắm hoặc PM tạo các PO (đơn đặt hàng), và nhà cung cấp bắt đầu công việc theo đó"},{"level":2,"text":"Quản lý hồ sơ và thanh toán"},{"level":2,"text":"Các đội kế toán, thu mua và mua sắm rà soát hồ sơ đơn hàng để xác định các sai lệch"},{"level":1,"text":"Các Tạo tác Mua sắm Phổ biến (Common Procurement Artifacts)"},{"level":2,"text":"Đơn Đặt hàng (Purchase Order - PO)"},{"level":2,"text":"Một yêu cầu do khách hàng đưa ra đối với hàng hóa hoặc dịch vụ cụ thể, khởi tạo một giao dịch"},{"level":2,"text":"Thỏa thuận Dịch vụ Tổng thể (Master Service Agreement - MSA) / Hợp đồng"},{"level":2,"text":"Tài liệu toàn diện phác thảo các điều khoản của mối quan hệ nhà cung cấp - người mua"},{"level":2,"text":"Hợp đồng thiết lập thỏa thuận mua một thứ gì đó, trong khi PO thực thi hợp đồng bằng cách khởi tạo các giao dịch mua cụ thể"},{"level":2,"text":"Hợp đồng Mua sắm (Procurement Contract)"},{"level":2,"text":"Phối hợp cùng PO để đảm bảo các điều khoản đã thỏa thuận được đáp ứng"},{"level":1,"text":"Hợp đồng Thuê (Lease)"},{"level":2,"text":"Hợp đồng có thời hạn cố định được thanh toán bằng một khoản phí ban đầu và các khoản thanh toán định kỳ trong suốt thời gian thuê"},{"level":2,"text":"Vào cuối hợp đồng, bạn thường có ba lựa chọn: trả tài sản cho chủ sở hữu, gia hạn hợp đồng thuê hoặc mua tài sản"},{"level":1,"text":"Đăng ký (Subscription) / Trả theo mức sử dụng (Pay-as-you-go)"},{"level":2,"text":"Mô hình thuê trọn gói được thanh toán bằng một khoản phí cố định để có quyền truy cập vào một nguồn lực trong một khoảng thời gian nhất định"},{"level":2,"text":"Hình thức đăng ký hoạt động tốt như một lựa chọn ít cần bảo trì với các mẫu mới nhất, hoặc cho việc sử dụng ngắn hạn hay khối lượng thấp, các hoạt động thử nghiệm (pilot) hoặc ngân sách nhỏ"},{"level":2,"text":"Nhà cung cấp dịch vụ đăng ký chi trả cho việc bảo trì và sửa chữa"},{"level":1,"text":"Các Tài liệu Khảo sát Khác nhau (Different Exploratory Documents)"},{"level":2,"text":"Yêu cầu Thông tin (Requests For Information - RFI)"},{"level":2,"text":"Một tài liệu dùng để thu thập thông tin về các nhà cung cấp tiềm năng và năng lực của họ"},{"level":2,"text":"Yêu cầu Đề xuất (Request For Proposal)"},{"level":2,"text":"Một tài liệu chính thức phác thảo nhu cầu của tổ chức và thu hút các đề xuất từ nhà cung cấp để cung cấp giải pháp hoặc dịch vụ đáp ứng các nhu cầu đó"},{"level":2,"text":"Yêu cầu Đấu thầu (Request For Bids - RFB)"},{"level":2,"text":"Tài liệu chính thức thu hút các hồ sơ đấu thầu từ nhà cung cấp để cung ứng hàng hóa hoặc dịch vụ"},{"level":2,"text":"Yêu cầu Báo giá (Requests For Quote - RFQ)"},{"level":2,"text":"Tài liệu chính thức thu hút các báo giá từ nhà cung cấp để cung ứng hàng hóa hoặc dịch vụ"}]},{"id":"g114","part":12,"title":"Đánh giá các Giải pháp","blocks":[{"level":1,"text":"Bản mô tả công việc (Statement of Work - SOW)"},{"level":2,"text":"Tài liệu chính thức quy định công việc mà nhà cung cấp phải hoàn thành"},{"level":2,"text":"3 Loại Bản mô tả công việc Chính (3 Main Types of Statement of Work)"},{"level":2,"text":"Bản mô tả công việc Thiết kế (Design Statement of Work)"},{"level":2,"text":"Mang tính chỉ định và chi tiết hóa quy trình cụ thể cùng các nguồn lực cần thiết để bàn giao công việc"},{"level":2,"text":"Bản mô tả công việc Chức năng (Functional Statement of Work)"},{"level":2,"text":"Tập trung vào kết quả và chỉ mô tả các yêu cầu của sản phẩm hoàn chỉnh"},{"level":2,"text":"Bản mô tả công việc Hiệu suất (Performance Statement of Work)"},{"level":2,"text":"Tập trung vào các kết quả mong đợi cùng với các tiêu chuẩn hiệu suất tối thiểu"},{"level":1,"text":"Điều khoản tham chiếu (Terms of Reference - TOR)"},{"level":2,"text":"Một phiên bản của bản mô tả công việc chứa cùng thông tin nhưng tập trung vào việc bàn giao công việc"},{"level":2,"text":"TOR là tài liệu chính thức tạo ra sự hiểu biết chung về phạm vi công việc hoặc kỳ vọng của một nhóm"},{"level":1,"text":"Các yếu tố của cả SOW và TOR đều giống nhau, bao gồm"},{"level":2,"text":"Bối cảnh và Tổng quan (Background and Overview)"},{"level":2,"text":"Các Yêu cầu (Requirements)"},{"level":2,"text":"Các Sản phẩm Bàn giao (Deliverables)"},{"level":2,"text":"Tiêu chuẩn Nghiệm thu (Standards for Acceptance)"},{"level":2,"text":"Lịch trình (Schedule)"},{"level":2,"text":"Điều khoản Thanh toán (Payment Terms)"},{"level":1,"text":"Chuyên gia mua sắm thực hiện nghiên cứu thị trường về một sản phẩm hoặc dịch vụ, các nhà cung cấp và xu hướng ngành"},{"level":1,"text":"Nghiên cứu thị trường có thể được thực hiện theo nhiều cách"},{"level":2,"text":"RFI"},{"level":2,"text":"Kết nối mạng lưới (Networking)"},{"level":2,"text":"Các Công ty Nghiên cứu (Research Firms)"},{"level":2,"text":"Demo hoặc Hội nghị (Demo or Conferences)"},{"level":2,"text":"Nghiên cứu Nội bộ (Internal Research)"},{"level":1,"text":"Phân tích cạnh tranh (Competitive analysis) thường được bàn cùng với nghiên cứu thị trường vì nó xem xét cùng thông tin từ một góc độ khác"},{"level":2,"text":"Trong khi nghiên cứu thị trường xác định danh sách các nhà cung cấp tiềm năng, phân tích cạnh tranh so sánh họ với nhau và đánh giá cách các công ty cạnh tranh trên thị trường"},{"level":1,"text":"Việc thực hiện nghiên cứu thị trường và phân tích cạnh tranh là các hoạt động mua sắm thực tế, diễn ra định kỳ"},{"level":1,"text":"Việc rà soát các lựa chọn mang lại cái nhìn sâu sắc cho quyết định thay đổi nhà cung cấp hoặc đàm phán lại các điều khoản"},{"level":1,"text":"Các cân nhắc đánh giá bao gồm các giải pháp thay thế và các lựa chọn nhà cung cấp hiện tại"},{"level":1,"text":"Khách hàng Xác định trước (Predetermined Client)"},{"level":2,"text":"Một người dùng mẫu hoặc một cấu hình ưu tiên giúp tối ưu hiệu suất của sản phẩm"},{"level":1,"text":"Chi phí Đầu tư và Chi phí Vận hành (Capital Expenses and Operational Expenses - CapEx and OpEx) là hai loại chi phí trong một tổ chức"},{"level":2,"text":"Chi phí Đầu tư (Capital Expenses - CapEx)"},{"level":2,"text":"Các tài sản cố định như trung tâm dữ liệu, phương tiện và thiết bị nằm ngoài ngân sách vận hành"},{"level":2,"text":"Chi phí Vận hành (Operational Expenses - OpEx)"},{"level":2,"text":"Các chi phí thường xuyên như lương, thuế, phí đăng ký, tiền thuê và tiện ích được đưa vào ngân sách và không khấu hao"},{"level":1,"text":"Đảm bảo rằng nhà cung cấp có đủ năng lực sản xuất (capacity), năng lực chuyên môn (capability) và sự quan tâm để đáp ứng các yêu cầu của dự án"}]});
